'use client'

/**
 * 权限模式详细说明 modal(2026-07-25 立,可解释性增强)
 *
 * 触发场景:
 * - 标题栏高风险模式(bypass-permissions)ⓘ 按钮点击
 * - 由 message-input 维护 [infoMode, setInfoMode] 状态,null 时关闭
 *
 * UI 组成:
 * - 顶部:模式图标 + 模式名 + 风险等级徽章
 * - 中部:4 条该模式详细行为 bullet
 * - 底部:"知道了"关闭按钮
 *
 * 数据流:
 * - 受控:mode 传 null → 关闭;非 null → 打开并展示对应模式详情
 * - 不持久化 React 状态
 *
 * 边界:
 * - mode 为 null → 不渲染(open=false)
 * - 与 PermissionShortcutsModal 互斥(同一时刻只一个打开,由父组件控制)
 */

import * as React from 'react'
import { useTranslations } from 'next-intl'
import { Hand, ShieldCheck, ShieldAlert, Info, X } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@ihui/ui-react'
import { cn } from '@/lib/utils'
import type { WorkspacePermissionMode } from '@ihui/api-client/endpoints/workspace'

type ModeConfig = {
  icon: React.ComponentType<{ className?: string }>
  titleKey: 'mode.ask' | 'mode.auto' | 'mode.full'
  riskCls: string
}

const MODE_CONFIG: Record<WorkspacePermissionMode, ModeConfig> = {
  default: {
    icon: Hand,
    titleKey: 'mode.ask',
    riskCls: 'bg-muted text-muted-foreground',
  },
  'accept-edits': {
    icon: ShieldCheck,
    titleKey: 'mode.auto',
    riskCls: 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-400',
  },
  'bypass-permissions': {
    icon: ShieldAlert,
    titleKey: 'mode.full',
    riskCls: 'bg-amber-500/10 text-amber-700 dark:text-amber-400',
  },
}

/** i18n 静态映射表 — 用于消除 `t(`modeInfoBullets.${mode}.${idx}`)` 双变量动态拼接 */
type ModeInfoBulletIdx = 0 | 1 | 2 | 3
const MODE_INFO_BULLETS_KEY: Record<WorkspacePermissionMode, Record<ModeInfoBulletIdx, string>> = {
  default: {
    0: 'modeInfoBullets.default.0',
    1: 'modeInfoBullets.default.1',
    2: 'modeInfoBullets.default.2',
    3: 'modeInfoBullets.default.3',
  },
  'accept-edits': {
    0: 'modeInfoBullets.accept-edits.0',
    1: 'modeInfoBullets.accept-edits.1',
    2: 'modeInfoBullets.accept-edits.2',
    3: 'modeInfoBullets.accept-edits.3',
  },
  'bypass-permissions': {
    0: 'modeInfoBullets.bypass-permissions.0',
    1: 'modeInfoBullets.bypass-permissions.1',
    2: 'modeInfoBullets.bypass-permissions.2',
    3: 'modeInfoBullets.bypass-permissions.3',
  },
}

export interface PermissionModeInfoModalProps {
  /** null = 关闭,非 null = 打开并展示该模式详情 */
  mode: WorkspacePermissionMode | null
  onClose: () => void
}

export function PermissionModeInfoModal({ mode, onClose }: PermissionModeInfoModalProps) {
  const t = useTranslations('chat.permission')
  return (
    <Dialog
      open={mode !== null}
      onOpenChange={(o) => {
        if (!o) onClose()
      }}
    >
      <DialogContent className="max-w-md">
        {mode ? (
          <>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <Info className="h-4 w-4" aria-hidden="true" />
                {t('infoModalTitle')}
              </DialogTitle>
              <DialogDescription>{t('infoModalDescription')}</DialogDescription>
            </DialogHeader>

            {(() => {
              const config = MODE_CONFIG[mode]
              const Icon = config.icon
              return (
                <div className="space-y-3">
                  <div className="flex items-center gap-2">
                    <span
                      className={cn(
                        'inline-flex h-9 w-9 items-center justify-center rounded-lg',
                        config.riskCls,
                      )}
                    >
                      <Icon className="h-4 w-4" aria-hidden="true" />
                    </span>
                    <div className="flex flex-col">
                      <span className="text-sm font-semibold text-foreground">
                        {t(config.titleKey)}
                      </span>
                    </div>
                  </div>

                  <ul className="space-y-1.5">
                    {[0, 1, 2, 3].map((idx) => (
                      <li
                        key={idx}
                        className="flex items-start gap-2 rounded-md border border-border/60 bg-card/40 px-2 py-1.5"
                      >
                        <span
                          className="mt-1 inline-block h-1.5 w-1.5 shrink-0 rounded-full bg-primary"
                          aria-hidden="true"
                        />
                        <span className="text-xs text-foreground">
                          {t(
                            MODE_INFO_BULLETS_KEY[mode]?.[idx as ModeInfoBulletIdx] ??
                              'modeInfoBullets.unknown',
                          )}
                        </span>
                      </li>
                    ))}
                  </ul>
                </div>
              )
            })()}

            <div className="flex justify-end pt-1">
              <button
                type="button"
                onClick={onClose}
                className="inline-flex items-center gap-1 rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground hover:bg-primary/90"
                data-testid="permission-mode-info-close"
              >
                {t('modeInfoAcknowledge')}
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            </div>
          </>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

export default PermissionModeInfoModal
