'use client'

/**
 * 权限模式快捷键帮助面板(2026-07-25 立,深度对标 OpenAI Codex CLI /help)
 *
 * 触发场景:
 * - ? 键(Shift+/)全局唤起/关闭,由 message-input 内 useEffect 监听
 * - 也可由外部组件通过 props.open = true 强制打开
 *
 * UI 组成:
 * - 标题栏:图标 + "权限模式快捷键" + 关闭按钮
 * - 3 分组:模式切换 / 高风险护栏 / 撤销与审计
 * - 每行:按键 + 动作描述
 *
 * 数据流:
 * - 受控:open + onClose 双向绑定
 * - 不持久化 React 状态(防 SSR hydration mismatch)
 *
 * 边界:
 * - 编辑控件焦点(typing):? 键不触发,由 message-input 的 useEffect 提前拦截
 * - 与 PermissionModeInfoModal 互斥(同一时刻只一个打开)
 */

import * as React from 'react'
import { useTranslations } from 'next-intl'
import { X, Keyboard, ShieldCheck, ShieldAlert, History, Hand, Undo2, TriangleAlert, SquareSlash, Layers, Hammer, BookOpen, Search, FileText } from 'lucide-react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@ihui/ui-react'
import { cn } from '@/lib/utils'

interface ShortcutRow {
  /** 按键标签(纯展示,如 "Shift+Tab" / "?" / "/permission full") */
  key: string
  /** 动作描述 i18n key */
  descKey: string
  /** 可选图标 */
  icon?: React.ComponentType<{ className?: string }>
}

interface ShortcutGroup {
  /** 分组标题 i18n key */
  titleKey: string
  rows: ShortcutRow[]
}

const SHORTCUT_GROUPS: ShortcutGroup[] = [
  {
    titleKey: 'shortcutsSectionSwitch',
    rows: [
      { key: 'Shift+Tab', descKey: 'shortcutsItemShiftTabKbd', icon: Hand },
      { key: '1 / 2 / 3', descKey: 'shortcutsItemNumberKbd', icon: Hand },
      {
        key: '/permission',
        descKey: 'shortcutsItemSlashAskKbd',
        icon: SquareSlash,
      },
    ],
  },
  {
    titleKey: 'shortcutsSectionGuard',
    rows: [
      { key: '?', descKey: 'shortcutsItemQuestionMarkKbd', icon: Keyboard },
      { key: 'ⓘ', descKey: 'shortcutsItemInfoKbd', icon: ShieldAlert },
    ],
  },
  {
    titleKey: 'shortcutsSectionAudit',
    rows: [
      { key: 'Undo 5s', descKey: 'shortcutsItemUndoKbd', icon: Undo2 },
      { key: '1h', descKey: 'shortcutsItemAutoRevert1hKbd', icon: TriangleAlert },
      { key: '查看历史', descKey: 'shortcutsItemHistoryKbd', icon: History },
    ],
  },
]

/**
 * 对话模式切换分组(2026-07-28 立,补全 ChatMode 4态三通道可发现性)。
 *
 * 与 SHORTCUT_GROUPS 分离的设计考量:
 * - SHORTCUT_GROUPS 走 next-intl t() 渲染,本组中文硬编码,i18n key 由后续 PR 注入
 * - 视觉风格(分组标题/行/kbd)与现有分组完全一致,无新增组件抽象
 *
 * 三通道可发现性(2026-07-28 v2:移除 ModeSwitcher 4 按钮后更新):
 * - Ctrl+1/2/3/4 全局快捷键(use-global-shortcuts.ts)
 * - /build /plan /review /spec 斜杠命令(message-input.tsx 解析)
 * - AI 自动判断(用户输入发送时由 use-chat.ts suggestMode 触发)
 * - 当前模式视觉指示:message-input.tsx CurrentModeBadge(小徽章,纯展示)
 */
interface ModeSwitchRow {
  /** 按键标签(如 "Ctrl+1" / "/build /plan /review /spec") */
  key: string
  /** 动作描述(中文硬编码,待 i18n) */
  desc: string
  /** 可选图标 */
  icon?: React.ComponentType<{ className?: string }>
}

const MODE_SWITCH_ROWS: ModeSwitchRow[] = [
  { key: 'Ctrl+1', desc: '切换到构建模式(正常执行,全工具开放)', icon: Hammer },
  { key: 'Ctrl+2', desc: '切换到计划模式(只读分析,deny write 工具)', icon: BookOpen },
  { key: 'Ctrl+3', desc: '切换到审查模式(只读审查 + 强化审查 prompt)', icon: Search },
  { key: 'Ctrl+4', desc: '切换到规格模式(从代码反向生成 spec 文档)', icon: FileText },
  { key: '/build /plan /review /spec', desc: '斜杠命令切换(也可用 Ctrl+1-4)', icon: SquareSlash },
]

export interface PermissionShortcutsModalProps {
  open: boolean
  onClose: () => void
}

export function PermissionShortcutsModal({ open, onClose }: PermissionShortcutsModalProps) {
  const t = useTranslations('chat.permission')
  return (
    <Dialog
      open={open}
      onOpenChange={(o) => {
        if (!o) onClose()
      }}
    >
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Keyboard className="h-4 w-4" aria-hidden="true" />
            {t('shortcutsModalTitle')}
          </DialogTitle>
          <DialogDescription>{t('shortcutsLearnMore')}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* 对话模式切换(2026-07-28 立,补全 ChatMode 4态三通道可发现性) */}
          <div className="space-y-2">
            <div className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
              <Layers className="h-3 w-3" aria-hidden="true" />
              <span>对话模式切换</span>
            </div>
            <ul className="space-y-1.5">
              {MODE_SWITCH_ROWS.map((row) => {
                const Icon = row.icon
                return (
                  <li
                    key={row.key}
                    className="flex items-center gap-2 rounded-md border border-border/60 bg-card/40 px-2 py-1.5"
                  >
                    <kbd
                      className={cn(
                        'inline-flex min-w-[88px] items-center justify-center gap-1 rounded-md',
                        'border border-border/60 bg-muted/40 px-2 py-0.5 font-mono text-[11px] text-foreground',
                      )}
                    >
                      {Icon ? <Icon className="h-3 w-3" aria-hidden="true" /> : null}
                      {row.key}
                    </kbd>
                    <span className="text-xs text-muted-foreground">{row.desc}</span>
                  </li>
                )
              })}
            </ul>
          </div>

          {SHORTCUT_GROUPS.map((group) => (
            <div key={group.titleKey} className="space-y-2">
              <div className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                {group.titleKey === 'shortcutsSectionSwitch' && <ShieldCheck className="h-3 w-3" />}
                {group.titleKey === 'shortcutsSectionGuard' && <ShieldAlert className="h-3 w-3" />}
                {group.titleKey === 'shortcutsSectionAudit' && <History className="h-3 w-3" />}
                <span>{t(group.titleKey)}</span>
              </div>
              <ul className="space-y-1.5">
                {group.rows.map((row) => {
                  const Icon = row.icon
                  return (
                    <li
                      key={row.key}
                      className="flex items-center gap-2 rounded-md border border-border/60 bg-card/40 px-2 py-1.5"
                    >
                      <kbd
                        className={cn(
                          'inline-flex min-w-[88px] items-center justify-center gap-1 rounded-md',
                          'border border-border/60 bg-muted/40 px-2 py-0.5 font-mono text-[11px] text-foreground',
                        )}
                      >
                        {Icon ? <Icon className="h-3 w-3" aria-hidden="true" /> : null}
                        {row.key}
                      </kbd>
                      <span className="text-xs text-muted-foreground">{t(row.descKey)}</span>
                    </li>
                  )
                })}
              </ul>
            </div>
          ))}
        </div>

        <div className="flex justify-end pt-1">
          <button
            type="button"
            onClick={onClose}
            className="inline-flex items-center gap-1 rounded-md bg-primary px-3 py-1.5 text-xs font-medium text-primary-foreground hover:bg-primary/90"
            data-testid="permission-shortcuts-close"
          >
            {t('shortcutsClose')}
            <X className="h-3 w-3" aria-hidden="true" />
          </button>
        </div>
      </DialogContent>
    </Dialog>
  )
}

export default PermissionShortcutsModal
